import React, { useState, useEffect } from 'react';
import axios from 'axios';
import api from  './';

function App() {
  const [user, setUser] = useState(null);
  const [files, setFiles] = useState([]);
  const [notices, setNotices] = useState([]);

  useEffect(() => {
    if (user) {
      api.post('/api/login', { email, password }).then(res => {
        setFiles(res.data.files);
        setNotices(res.data.notices);
      });
    }
  }, [user]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  return user.role === 'admin' ? (
    <AdminPanel user={user} />
  ) : (
    <UserPanel files={files} notices={notices} />
  );
}

function Login({ onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  function handleLogin() {
    api.post('/api/login', { email, password })
      .then(res => onLogin(res.data.user))
      .catch(() => alert('Email ou senha inválidos'));
  }

  return (
    <div style={{ maxWidth: 400, margin: '2rem auto', padding: '1rem', border: '1px solid #ccc', borderRadius: 8 }}>
      <h2>Painel do Licenciado</h2>
      <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} style={{ width: '100%', padding: 8, marginBottom: 8 }} />
      <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} style={{ width: '100%', padding: 8, marginBottom: 16 }} />
      <button onClick={handleLogin} style={{ width: '100%', padding: 10, backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: 4 }}>Entrar</button>
    </div>
  );
}

function UserPanel({ files, notices }) {
  return (
    <div style={{ maxWidth: 600, margin: '2rem auto', padding: '1rem' }}>
      <h1>Painel do Licenciado</h1>
      <h2>Comunicados</h2>
      <ul>
        {notices.map((n, i) => (
          <li key={i}>{n}</li>
        ))}
      </ul>
      <h2>Arquivos para Download</h2>
      <ul>
        {files.map((f, i) => (
          <li key={i}>
            <a href={f.url} target="_blank" rel="noopener noreferrer">{f.name}</a>
          </li>
        ))}
      </ul>
    </div>
  );
}

function AdminPanel({ user }) {
  const [noticeText, setNoticeText] = useState('');
  const [file, setFile] = useState(null);
  const [status, setStatus] = useState('');

  function handleNoticeSubmit() {
    api.post('/api/admin/notice', { text: noticeText })
      .then(() => {
        setStatus('Comunicado enviado');
        setNoticeText('');
      });
  }

  function handleFileUpload() {
    const formData = new FormData();
    formData.append('file', file);
    api.post('/api/admin/upload', formData)
      .then(() => {
        setStatus('Arquivo enviado');
        setFile(null);
      });
  }

  return (
    <div style={{ maxWidth: 400, margin: '2rem auto', padding: '1rem' }}>
      <h1>Painel do Administrador</h1>

      <h2>Postar Comunicado</h2>
      <textarea value={noticeText} onChange={e => setNoticeText(e.target.value)} style={{ width: '100%', height: 80, marginBottom: 8 }} />

      <button onClick={handleNoticeSubmit} style={{ width: '100%', padding: 10, backgroundColor: 'green', color: 'white', border: 'none', borderRadius: 4, marginBottom: 16 }}>
        Enviar Comunicado
      </button>

      <h2>Enviar Arquivo</h2>
      <input type="file" onChange={e => setFile(e.target.files[0])} style={{ marginBottom: 8 }} />

      <button onClick={handleFileUpload} style={{ width: '100%', padding: 10, backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: 4 }}>
        Upload
      </button>

      {status && <p style={{ marginTop: 12, color: 'green' }}>{status}</p>}
    </div>
  );
}

export default App;
